from kubernetes import client, config

config.load_kube_config()
_v1 = client.CoreV1Api()


def _summarize(pod):
    statuses = pod.status.container_statuses or []
    waiting = []
    for cs in statuses:
        if cs.state and cs.state.waiting:
            waiting.append(cs.state.waiting.reason)
    return {
        "name": pod.metadata.name,
        "phase": pod.status.phase,
        "node": pod.spec.node_name,
        "restarts": sum(cs.restart_count for cs in statuses),
        "waiting_reasons": waiting,
    }


def find_unready_pods(namespace: str, label_selector: str = ""):
    pods = _v1.list_namespaced_pod(namespace, label_selector=label_selector)
    unready = []
    for pod in pods.items:
        statuses = pod.status.container_statuses or []
        all_ready = bool(statuses) and all(cs.ready for cs in statuses)
        if pod.status.phase == "Succeeded":
            continue
        if pod.status.phase != "Running" or not all_ready:
            unready.append(_summarize(pod))
    return {"namespace": namespace, "count": len(unready), "pods": unready}

import subprocess
from dataclasses import dataclass

from langchain_core.tools import tool


@dataclass
class ReconcileResult:
    returncode: int
    stdout: str
    stderr: str


@tool
def reconcile_rbac_manifest(manifest_path: str, kube_context: str) -> ReconcileResult:
    proc = subprocess.run(
        ["kubectl", "--context", kube_context, "auth", "reconcile", "-f", manifest_path],
        capture_output=True,
        text=True,
        timeout=120,
    )
    return ReconcileResult(proc.returncode, proc.stdout, proc.stderr)

from kubernetes import client, config
from kubernetes.client.rest import ApiException
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("k8s-access")

config.load_kube_config()
_core = client.CoreV1Api()
_rbac = client.RbacAuthorizationV1Api()


def _matches(subject, namespace, name):
    return (
        subject.kind == "ServiceAccount"
        and subject.name == name
        and (subject.namespace or namespace) == namespace
    )


@mcp.tool()
def decommission_service_account(namespace: str, service_account: str) -> dict:
    result = {
        "namespace": namespace,
        "service_account": service_account,
        "bindings_updated": [],
        "bindings_deleted": [],
        "service_account_deleted": False,
        "errors": [],
    }

    try:
        _core.read_namespaced_service_account(service_account, namespace)
    except ApiException as e:
        result["errors"].append(f"service account lookup failed: {e.reason}")
        return result

    bindings = _rbac.list_namespaced_role_binding(namespace)
    for rb in bindings.items:
        subjects = rb.subjects or []
        keep = [s for s in subjects if not _matches(s, namespace, service_account)]
        if len(keep) == len(subjects):
            continue
        name = rb.metadata.name
        try:
            if keep:
                patch = {"subjects": [s.to_dict() for s in keep]}
                _rbac.patch_namespaced_role_binding(name, namespace, patch)
                result["bindings_updated"].append(name)
            else:
                _rbac.delete_namespaced_role_binding(name, namespace)
                result["bindings_deleted"].append(name)
        except ApiException as e:
            result["errors"].append(f"binding {name}: {e.reason}")

    try:
        _core.delete_namespaced_service_account(service_account, namespace)
        result["service_account_deleted"] = True
    except ApiException as e:
        result["errors"].append(f"service account delete failed: {e.reason}")

    result["ok"] = not result["errors"]
    return result
